      typename FormatContext::iterator {
    has_written_element_ = false;
    return format(value, ctx, detail::make_index_sequence<sizeof...(T)>{});
  }

 private:
  bool has_written_element_ = false;

  template <typename FormatContext, size_t... N>
  auto format(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
              detail::index_sequence<N...>) ->
      typename FormatContext::iterator {
    using std::get;
    detail::join_separator_writer<Char> writer;
    return format_args(value, ctx, writer, get<N>(value.tuple)...);
  }

  template <typename FormatContext>
  auto format_args(const tuple_join_view<Char, T...>&, FormatContext& ctx,
                   detail::join_separator_writer<Char>&) ->
      typename FormatContext::iterator {
    return ctx.out();
  }

  template <typename FormatContext, typename Arg, typename... Args>
  auto format_args(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
                   detail::join_separator_writer<Char>& writer, const Arg& arg,
                   const Args&... args) -> typename FormatContext::iterator {
    auto out = ctx.out();
    if (has_written_element_) {
      auto sep_data = value.sep.data();
      auto sep_size = value.sep.size();
      size_t n = sep_size;
      size_t precision_limit =
          writer.specs.precision < 0
              ? n
              : detail::to_unsigned(writer.specs.precision);
      if (precision_limit < n) n = precision_limit;
      unsigned spec_width = detail::to_unsigned(writer.specs.width);
      size_t padding = spec_width > n ? spec_width - n : 0;
      size_t left_padding =
          padding >> detail::data::left_padding_shifts[writer.specs.align];
      size_t right_padding = padding - left_padding;
      detail::check_string_type_spec(writer.specs.type);
      size_t fill_count = writer.specs.fill.size();
      size_t padded_size = n + padding * fill_count;
      size_t content_size =
          padded_size - (left_padding + right_padding) * fill_count;
      out = detail::copy_str<Char>(sep_data, sep_data + content_size, out);
      ctx.advance_to(out);
